// MARK: - Audit Logger
class AuditLogger {
    private let queue = DispatchQueue(label: "audit.log", qos: .utility)
    private var logFile: FileHandle?

    init(path: String) {
        FileManager.default.createFile(atPath: path, contents: nil)
        self.logFile = FileHandle(forWritingAtPath: path)
    }

    func log(_ event: String, metadata: [String: String] = [:]) {
        queue.async { [weak self] in
            let timestamp = ISO8601DateFormatter().string(from: Date())
            let metaStr = metadata.map { "\($0.key)=\($0.value)" }.joined(separator: ",")
            let entry = "[\(timestamp)] \(event) {\(metaStr)}\n"
            self?.logFile?.write(entry.data(using: .utf8) ?? Data())
        }
    }
}

// MARK: - NTLM Authentication Context
struct NTLMContext {
    let negotiateFlags: UInt32
    let targetName: String
    let challenge: Data
    let channelBinding: Data?

    var requiresMIC: Bool {
        return (negotiateFlags & 0x00200000) != 0 // NTLMSSP_NEGOTIATE_SIGN
    }
}

// MARK: - Authentication Validator
class NTLMAuthValidator {
    private let auditLogger: AuditLogger
    private var pendingContexts: [String: NTLMContext] = [:]
    private let contextLock = NSLock()

    init(logger: AuditLogger) {
        self.auditLogger = logger
    }

    func createChallenge(sessionId: String, targetName: String) -> Data {
        let challenge = generateSecureRandom(count: 8)
        let flags: UInt32 = 0x00228233 // Standard negotiate flags with signing
        let ctx = NTLMContext(
            negotiateFlags: flags,
            targetName: targetName,
            challenge: challenge,
            channelBinding: nil
        )
        contextLock.lock()
        pendingContexts[sessionId] = ctx
        contextLock.unlock()

        auditLogger.log("ntlm_challenge_issued", metadata: [
            "session": sessionId,
            "target": targetName
        ])
        return challenge
    }

    func validateAuthentication(sessionId: String, authMessage: Data, channelBindings: Data?) -> Bool {
        contextLock.lock()
        guard let ctx = pendingContexts[sessionId] else {
            contextLock.unlock()
            auditLogger.log("ntlm_auth_failed", metadata: ["reason": "no_context"])
            return false
        }
        pendingContexts.removeValue(forKey: sessionId)
        contextLock.unlock()

        // Validate MIC if negotiated
        let micValid = validateMIC(context: ctx, authMessage: authMessage)

        // Channel binding validation
        let cbValid = validateChannelBindings(
            expected: channelBindings,
            context: ctx,
            authMessage: authMessage
        )

        let authResult = micValid && cbValid

        auditLogger.log("ntlm_auth_result", metadata: [
            "session": sessionId,
            "mic_valid": String(micValid),
            "cb_valid": String(cbValid),
            "result": String(authResult)
        ])

        return authResult
    }

    private func validateMIC(context: NTLMContext, authMessage: Data) -> Bool {
        guard context.requiresMIC else {
            return true // MIC not required by negotiation
        }
        // Extract MIC from auth message offset 72, length 16
        guard authMessage.count >= 88 else { return false }
        let mic = authMessage.subdata(in: 72..<88)
        // In real implementation, compute expected MIC
        return !mic.allSatisfy { $0 == 0 }
    }

    private func validateChannelBindings(expected: Data?, context: NTLMContext, authMessage: Data) -> Bool {
        // EPA (Extended Protection for Authentication) check
        guard let expectedCB = expected else {
            // No channel bindings provided by transport layer
            // This is the critical decision point
            return true
        }
        guard let contextCB = context.channelBinding else {
            return true
        }
        return expectedCB == contextCB
    }
}

// MARK: - Background Job Worker
class BackgroundJobWorker {
    private let validator: NTLMAuthValidator
    private let auditLogger: AuditLogger
    private let jobQueue = DispatchQueue(label: "worker.jobs", attributes: .concurrent)

    init() {
        self.auditLogger = AuditLogger(path: "/var/log/worker_audit.log")
        self.validator = NTLMAuthValidator(logger: auditLogger)
    }

    func processIncomingConnection(sessionId: String, tlsChannelId: Data?, authData: Data) {
        jobQueue.async { [weak self] in
            guard let self = self else { return }

            self.auditLogger.log("connection_received", metadata: [
                "session": sessionId,
                "has_tls": String(tlsChannelId != nil)
            ])

            // Phase 1: Issue challenge
            let challenge = self.validator.createChallenge(
                sessionId: sessionId,
                targetName: "WORKGROUP"
            )

            // Phase 2: Validate auth response
            // Pass TLS channel binding token for EPA validation
            let authenticated = self.validator.validateAuthentication(
                sessionId: sessionId,
                authMessage: authData,
                channelBindings: tlsChannelId
            )

            if authenticated {
                self.auditLogger.log("job_authorized", metadata: ["session": sessionId])
                self.executeJob(sessionId: sessionId)
            } else {
                self.auditLogger.log("job_rejected", metadata: ["session": sessionId])
            }
        }
    }

    private func executeJob(sessionId: String) {
        auditLogger.log("job_executing", metadata: ["session": sessionId])
    }
}

// MARK: - Utilities
func generateSecureRandom(count: Int) -> Data {
    var bytes = [UInt8](repeating: 0, count: count)
    _ = SecRandomCopyBytes(kSecRandomDefault, count, &bytes)
    return Data(bytes)
}
